@php
    $nights = max(1, \Carbon\Carbon::parse($checkIn ?? now()->addDay())->diffInDays(\Carbon\Carbon::parse($checkOut ?? now()->addDays(2))));
    $roomPricePerNight = (float) ($selectedRoom->price_per_night ?? ($property->price_per_night ?? 2500));
    $rawSubtotal = $roomPricePerNight * $nights;
    $couponDiscount = 500;
    $finalTotal = max(0, $rawSubtotal - $couponDiscount);
@endphp
