  <script>
    (function() {
      console.log("Prime Booking Funnel Activated!");

      function init() {
        const step1Section = document.getElementById("step1Section");
        const step2Section = document.getElementById("step2Section");
        const step3Section = document.getElementById("step3Section");

        const fNameInput = document.getElementById("contact.contactFirstName");
        const lNameInput = document.getElementById("contact.contactLastName");
        const emailInput = document.getElementById("contact.contactEmail");
        const phoneInput = document.getElementById("contact.contactPhoneNumber");

        function getCookie(name) {
          const v = document.cookie.match('(^|;) ?' + name + '=([^;]*)(;|$)');
          return v ? v[2] : null;
        }
        const csrfToken = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || getCookie('XSRF-TOKEN') || '';

        // Stepper Visual State Manager
        function setStepperStep(activeStep) {
          [1, 2, 3].forEach(s => {
            const spans = Array.from(document.querySelectorAll('span, div')).filter(el => {
              const text = (el.textContent || '').trim();
              return text === String(s) && el.style && (el.style.borderRadius === '50%' || el.classList.contains('abb64-rounded-max'));
            });
            spans.forEach(span => {
              if (s < activeStep) {
                span.style.background = '#16a34a';
                span.style.color = '#ffffff';
                span.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg>';
              } else if (s === activeStep) {
                span.style.background = '#2067da';
                span.style.color = '#ffffff';
                span.textContent = String(s);
              } else {
                span.style.background = '#f1f5f9';
                span.style.color = '#64748b';
                span.textContent = String(s);
              }
            });
          });
        }

        // Special Requests Interactive Radios
        window.selectedSmoking = 'Non-smoking';
        window.selectedBed = "I'd like a large bed";

        const nonSmokingOption = document.querySelector('[data-element-name="NonSmoking"]');
        const smokingOption = document.querySelector('[data-element-name="Smoking"]');
        const largeBedOption = document.querySelector('[data-element-name="LargeBed"]');
        const twinBedsOption = document.querySelector('[data-element-name="TwinBeds"]');

        function updateRadioDot(el, isSelected) {
          if (!el) return;
          const dot = el.querySelector('.RadioButtonstyled__RadioButtonStyled-sc-1cxijc0-0') || el.querySelector('[class*="RadioButtonStyled"]');
          if (dot) {
            if (isSelected) {
              dot.style.borderColor = '#2067da';
              dot.style.backgroundColor = '#2067da';
              dot.style.boxShadow = 'inset 0 0 0 3px #ffffff';
            } else {
              dot.style.borderColor = '#94a3b8';
              dot.style.backgroundColor = 'transparent';
              dot.style.boxShadow = 'none';
            }
          }
        }

        if (nonSmokingOption) {
          nonSmokingOption.style.cursor = 'pointer';
          nonSmokingOption.onclick = function(e) {
            e.preventDefault();
            window.selectedSmoking = 'Non-smoking';
            updateRadioDot(nonSmokingOption, true);
            updateRadioDot(smokingOption, false);
          };
          updateRadioDot(nonSmokingOption, true);
        }

        if (smokingOption) {
          smokingOption.style.cursor = 'pointer';
          smokingOption.onclick = function(e) {
            e.preventDefault();
            window.selectedSmoking = 'Smoking';
            updateRadioDot(smokingOption, true);
            updateRadioDot(nonSmokingOption, false);
          };
        }

        if (largeBedOption) {
          largeBedOption.style.cursor = 'pointer';
          largeBedOption.onclick = function(e) {
            e.preventDefault();
            window.selectedBed = "I'd like a large bed";
            updateRadioDot(largeBedOption, true);
            updateRadioDot(twinBedsOption, false);
          };
          updateRadioDot(largeBedOption, true);
        }

        if (twinBedsOption) {
          twinBedsOption.style.cursor = 'pointer';
          twinBedsOption.onclick = function(e) {
            e.preventDefault();
            window.selectedBed = "I'd like twin beds";
            updateRadioDot(twinBedsOption, true);
            updateRadioDot(largeBedOption, false);
          };
        }

        // Additional Preferences Toggle
        const moreToggle = document.getElementById('specialRequests.moreRequestToggle') || document.querySelector('[data-testid="specialRequests.moreRequestToggle"]');
        if (moreToggle) {
          moreToggle.style.cursor = 'pointer';
          moreToggle.onclick = function(e) {
            e.preventDefault();
            let extraPanel = document.getElementById('agodaExtraPreferencesPanel');
            if (!extraPanel) {
              extraPanel = document.createElement('div');
              extraPanel.id = 'agodaExtraPreferencesPanel';
              extraPanel.style.marginTop = '12px';
              extraPanel.style.padding = '14px 16px';
              extraPanel.style.background = '#f8fafc';
              extraPanel.style.border = '1px solid #e2e8f0';
              extraPanel.style.borderRadius = '8px';
              extraPanel.innerHTML = `
                <div style="font-weight:700;font-size:13px;color:#1e293b;margin-bottom:8px;">Extra Room &amp; Arrival Preferences (Optional):</div>
                <div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(200px, 1fr));gap:8px;font-size:12.5px;color:#334155;">
                  <label style="cursor:pointer;display:flex;align-items:center;gap:6px;"><input type="checkbox" id="pref_high_floor" value="High floor"> <span>High floor</span></label>
                  <label style="cursor:pointer;display:flex;align-items:center;gap:6px;"><input type="checkbox" id="pref_low_floor" value="Low floor"> <span>Low floor</span></label>
                  <label style="cursor:pointer;display:flex;align-items:center;gap:6px;"><input type="checkbox" id="pref_quiet" value="Quiet room"> <span>Quiet room</span></label>
                  <label style="cursor:pointer;display:flex;align-items:center;gap:6px;"><input type="checkbox" id="pref_early_checkin" value="Early check-in"> <span>Early check-in request</span></label>
                  <label style="cursor:pointer;display:flex;align-items:center;gap:6px;"><input type="checkbox" id="pref_late_checkout" value="Late check-out"> <span>Late check-out request</span></label>
                  <label style="cursor:pointer;display:flex;align-items:center;gap:6px;"><input type="checkbox" id="pref_airport" value="Airport transfer"> <span>Airport transfer assistance</span></label>
                </div>
                <div style="margin-top:10px;">
                  <label style="font-size:12px;font-weight:600;color:#475569;display:block;margin-bottom:4px;">Additional remarks or hotel requests:</label>
                  <textarea id="specialRequestNotes" placeholder="Write any specific request here. Hotel will do its best upon check-in." style="width:100%;padding:8px 10px;font-size:12px;border:1px solid #cbd5e1;border-radius:6px;min-height:55px;resize:vertical;"></textarea>
                </div>
              `;
              moreToggle.parentNode.appendChild(extraPanel);
            } else {
              extraPanel.style.display = (extraPanel.style.display === 'none') ? 'block' : 'none';
            }
          };
        }

        // NEXT STEP BUTTONS in Step 1
        const nextButtons = Array.from(document.querySelectorAll("#step1Section button")).filter(b => {
          const t = (b.textContent || "").trim();
          return t.includes("NEXT") || t.includes("FINAL STEP") || b.getAttribute('data-action') === 'nextPage';
        });

        nextButtons.forEach(btn => {
          btn.onclick = function(e) {
            e.preventDefault();
            const fVal = fNameInput ? fNameInput.value.trim() : "";
            const lVal = lNameInput ? lNameInput.value.trim() : "";
            const eVal = emailInput ? emailInput.value.trim() : "";
            const pVal = phoneInput ? phoneInput.value.trim() : "";

            if (!fVal || !lVal || !eVal || !pVal) {
              alert("Please complete First Name, Last Name, Email, and Mobile number before proceeding.");
              if (!fVal && fNameInput) fNameInput.focus();
              else if (!lVal && lNameInput) lNameInput.focus();
              else if (!eVal && emailInput) emailInput.focus();
              else if (!pVal && phoneInput) phoneInput.focus();
              return;
            }

            // Sync cardholder name in step 2
            const cardHolder = document.querySelector("#step2Section input[name='cardHolderName']");
            if (cardHolder) {
              cardHolder.value = (fVal + " " + lVal).trim();
            }

            step1Section.classList.add("step-hidden");
            step2Section.classList.remove("step-hidden");
            step3Section.classList.add("step-hidden");
            setStepperStep(2);
            window.scrollTo({ top: 0, behavior: "smooth" });
          };
        });

        // Handle Back To Guest Details
        const backButtons = Array.from(document.querySelectorAll("#step2Section button")).filter(b => {
          const t = (b.textContent || "").trim();
          return t.includes("Back") || t.includes("guest details") || b.id === 'btnBackToGuest';
        });
        backButtons.forEach(btn => {
          btn.onclick = function(e) {
            if (e) e.preventDefault();
            step2Section.classList.add("step-hidden");
            step1Section.classList.remove("step-hidden");
            step3Section.classList.add("step-hidden");
            setStepperStep(1);
            window.scrollTo({ top: 0, behavior: "smooth" });
          };
        });

        // PAYMENT METHOD SWITCHING & MFS HANDLING
        let selectedPaymentMethod = 'sslcommerz';
        let selectedDigitalWallet = 'bkash';

        const cardCategoryLabel = document.querySelector('label[data-component="payment-category-selection-1"]');
        const digitalCategoryLabel = document.querySelector('label[data-component="payment-category-selection-3"]');
        const cardContentArea = document.querySelector('div[data-testid="credit-debit-card-category-content"]');
        const digitalContentArea = document.getElementById('digitalPaymentCategoryContent');

        function updateBookNowBtnText() {
          const payButtons = Array.from(document.querySelectorAll("#step2Section button[data-testid='shimmer-cta'], #step2Section button")).filter(b => {
            const t = (b.textContent || "").trim();
            return t.includes("BOOK NOW") || b.getAttribute('data-action') === 'book';
          });

          payButtons.forEach(btn => {
            const spanText = btn.querySelector('.eOlZUF') || btn.querySelector('span') || btn;
            const amountStr = '৳ {{ number_format($finalTotal) }}';
            if (selectedPaymentMethod === 'bkash') {
              spanText.textContent = 'PAY WITH BKASH ' + amountStr;
            } else if (selectedPaymentMethod === 'nagad') {
              spanText.textContent = 'PAY WITH NAGAD ' + amountStr;
            } else if (selectedPaymentMethod === 'rocket') {
              spanText.textContent = 'PAY WITH ROCKET ' + amountStr;
            } else {
              spanText.textContent = 'BOOK NOW - PAY WITH CARD';
            }
          });
        }

        function setPaymentMethod(method) {
          selectedPaymentMethod = method;
          const isCard = (method === 'sslcommerz' || method === 'card');

          if (cardCategoryLabel) {
            const cardRadioDot = cardCategoryLabel.querySelector('.RadioButtonstyled__RadioButtonStyled-sc-1cxijc0-0');
            if (cardRadioDot) {
              if (isCard) {
                cardRadioDot.style.borderColor = '#2067da';
                cardRadioDot.style.backgroundColor = '#2067da';
                cardRadioDot.style.boxShadow = 'inset 0 0 0 3px #ffffff';
              } else {
                cardRadioDot.style.borderColor = '#94a3b8';
                cardRadioDot.style.backgroundColor = 'transparent';
                cardRadioDot.style.boxShadow = 'none';
              }
            }
          }

          if (digitalCategoryLabel) {
            const digitalRadioDot = digitalCategoryLabel.querySelector('.RadioButtonstyled__RadioButtonStyled-sc-1cxijc0-0');
            if (digitalRadioDot) {
              if (!isCard) {
                digitalRadioDot.style.borderColor = '#2067da';
                digitalRadioDot.style.backgroundColor = '#2067da';
                digitalRadioDot.style.boxShadow = 'inset 0 0 0 3px #ffffff';
              } else {
                digitalRadioDot.style.borderColor = '#94a3b8';
                digitalRadioDot.style.backgroundColor = 'transparent';
                digitalRadioDot.style.boxShadow = 'none';
              }
            }
          }

          if (cardContentArea) {
            cardContentArea.style.display = isCard ? 'block' : 'none';
          }

          if (digitalContentArea) {
            digitalContentArea.style.display = isCard ? 'none' : 'block';
          }

          updateBookNowBtnText();
        }

        // Attach click listeners to Payment category headers
        if (cardCategoryLabel) {
          cardCategoryLabel.style.cursor = 'pointer';
          cardCategoryLabel.onclick = function(e) {
            e.preventDefault();
            setPaymentMethod('sslcommerz');
          };
        }

        if (digitalCategoryLabel) {
          digitalCategoryLabel.style.cursor = 'pointer';
          digitalCategoryLabel.onclick = function(e) {
            e.preventDefault();
            setPaymentMethod(selectedDigitalWallet || 'bkash');
          };
        }

        // Wallet selection inside digital payment
        window.selectPrimeWallet = function(walletName) {
          selectedDigitalWallet = walletName;
          selectedPaymentMethod = walletName;

          const wallets = [
            { id: 'mfsWalletBkash', color: '#e11d48', name: 'bkash' },
            { id: 'mfsWalletNagad', color: '#f59e0b', name: 'nagad' },
            { id: 'mfsWalletRocket', color: '#7c3aed', name: 'rocket' }
          ];

          wallets.forEach(w => {
            const el = document.getElementById(w.id);
            if (!el) return;
            const tag = el.querySelector('.mfs-active-tag');
            if (w.name === walletName) {
              el.style.border = '2px solid ' + w.color;
              el.style.boxShadow = '0 2px 8px rgba(0,0,0,0.12)';
              if (tag) tag.style.display = 'block';
            } else {
              el.style.border = '1.5px solid #e2e8f0';
              el.style.boxShadow = 'none';
              if (tag) tag.style.display = 'none';
            }
          });

          updateBookNowBtnText();
        };

        const wBkash = document.getElementById('mfsWalletBkash');
        const wNagad = document.getElementById('mfsWalletNagad');
        const wRocket = document.getElementById('mfsWalletRocket');
        if (wBkash) wBkash.onclick = () => window.selectPrimeWallet('bkash');
        if (wNagad) wNagad.onclick = () => window.selectPrimeWallet('nagad');
        if (wRocket) wRocket.onclick = () => window.selectPrimeWallet('rocket');

        // Card Auto-Formatting
        const cardNumInput = document.querySelector("#step2Section input[name='cardNumber']");
        if (cardNumInput) {
          cardNumInput.addEventListener('input', function() {
            let val = this.value.replace(/\D/g, '').substring(0, 16);
            let formatted = val.match(/.{1,4}/g)?.join(' ') || val;
            this.value = formatted;
          });
        }

        const expiryInput = document.querySelector("#step2Section input[name='expiryDate']");
        if (expiryInput) {
          expiryInput.addEventListener('input', function() {
            let val = this.value.replace(/\D/g, '').substring(0, 4);
            if (val.length >= 3) {
              this.value = val.substring(0, 2) + '/' + val.substring(2);
            } else {
              this.value = val;
            }
          });
        }

        const cvvInput = document.querySelector("#step2Section input[name='cvv']");
        if (cvvInput) {
          cvvInput.addEventListener('input', function() {
            this.value = this.value.replace(/\D/g, '').substring(0, 4);
          });
        }

        // Initialize Card as active
        setPaymentMethod('sslcommerz');

        // BOOK NOW Click handler
        const payButtons = Array.from(document.querySelectorAll("#step2Section button[data-testid='shimmer-cta'], #step2Section button")).filter(b => {
          const t = (b.textContent || "").trim();
          return t.includes("BOOK NOW") || b.getAttribute('data-action') === 'book';
        });

        payButtons.forEach(btn => {
          btn.onclick = function(e) {
            e.preventDefault();

            // Card validation if Card is selected
            if (selectedPaymentMethod === 'sslcommerz' || selectedPaymentMethod === 'card') {
              const cNum = cardNumInput ? cardNumInput.value.replace(/\s/g, '') : '';
              const exp = expiryInput ? expiryInput.value.trim() : '';
              const cvv = cvvInput ? cvvInput.value.trim() : '';

              if (cNum.length < 13) {
                alert('Please enter a valid Credit or Debit Card Number.');
                if (cardNumInput) cardNumInput.focus();
                return;
              }
              if (!exp.includes('/') || exp.length < 5) {
                alert('Please enter a valid expiry date (MM/YY).');
                if (expiryInput) expiryInput.focus();
                return;
              }
              if (cvv.length < 3) {
                alert('Please enter a valid 3 or 4-digit CVV / CVC code.');
                if (cvvInput) cvvInput.focus();
                return;
              }
            }

            const originalHtml = btn.innerHTML;
            btn.disabled = true;
            btn.innerHTML = '<span style="display:inline-flex; align-items:center; gap:8px;"><svg class="animate-spin" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10" stroke-opacity="0.25"></circle><path d="M12 2a10 10 0 0 1 10 10" stroke-opacity="1"></path></svg> Processing Booking...</span>';

            const fullGuestName = ((fNameInput ? fNameInput.value.trim() : "") + " " + (lNameInput ? lNameInput.value.trim() : "")).trim() || "Guest Traveler";
            const guestEmail = (emailInput ? emailInput.value.trim() : "") || "traveler@primebooking.com.bd";
            const guestPhone = (phoneInput ? phoneInput.value.trim() : "") || "01700000000";

            // Build detailed special requests string
            const reqParts = [];
            if (typeof selectedSmoking !== 'undefined' && selectedSmoking) reqParts.push("Room: " + selectedSmoking);
            if (typeof selectedBed !== 'undefined' && selectedBed) reqParts.push("Bed: " + selectedBed);
            
            const extraSelected = [];
            ['pref_high_floor', 'pref_low_floor', 'pref_quiet', 'pref_early_checkin', 'pref_late_checkout', 'pref_airport'].forEach(id => {
              const el = document.getElementById(id);
              if (el && el.checked) extraSelected.push(el.value);
            });
            if (extraSelected.length > 0) {
              reqParts.push("Preferences: " + extraSelected.join(", "));
            }
            const notesEl = document.getElementById('specialRequestNotes');
            if (notesEl && notesEl.value.trim()) {
              reqParts.push("Guest Notes: " + notesEl.value.trim());
            }
            const fullSpecialRequests = reqParts.join(" | ");

            // Submit booking directly to backend with CSRF token
            fetch('{{ route("booking.store", $property->id) }}', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Accept': 'application/json',
                'X-CSRF-TOKEN': csrfToken,
                'X-Requested-With': 'XMLHttpRequest'
              },
              body: JSON.stringify({
                _token: csrfToken,
                guest_name: fullGuestName,
                guest_email: guestEmail,
                guest_phone: guestPhone,
                check_in: '{{ $checkIn }}',
                check_out: '{{ $checkOut }}',
                guests: {{ (int)$guests }},
                room_id: {{ $selectedRoom ? $selectedRoom->id : ($property->rooms->first()?->id ?? 1) }},
                payment_method: selectedPaymentMethod,
                special_requests: fullSpecialRequests
              })
            }).then(r => r.json()).then(data => {
              if (data && data.redirect_url) {
                btn.innerHTML = '<span style="display:inline-flex; align-items:center; gap:8px;"><svg class="animate-spin" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10" stroke-opacity="0.25"></circle><path d="M12 2a10 10 0 0 1 10 10" stroke-opacity="1"></path></svg> Connecting to Gateway...</span>';
                window.location.href = data.redirect_url;
              } else if (data && data.booking_reference) {
                const vRef = document.getElementById('vBookingRef');
                if (vRef) vRef.textContent = data.booking_reference;

                const pdfLink = document.getElementById('btnViewVoucherPdf');
                if (pdfLink) {
                  pdfLink.href = '/booking/voucher/' + data.booking_reference;
                }

                const vName = document.getElementById('vGuestName');
                if (vName) vName.textContent = fullGuestName;
                const vEmail = document.getElementById('vGuestEmail');
                if (vEmail) vEmail.textContent = guestEmail;

                step1Section.classList.add('step-hidden');
                step2Section.classList.add('step-hidden');
                step3Section.classList.remove('step-hidden');
                setStepperStep(3);
                window.scrollTo({ top: 0, behavior: 'smooth' });
              } else {
                alert((data && data.message) ? data.message : 'Reservation could not be placed. Please check your contact information and try again.');
                btn.disabled = false;
                btn.innerHTML = originalHtml;
              }
            }).catch(err => {
              console.error('Booking submission error:', err);
              alert('Network error while completing booking. Please try again.');
              btn.disabled = false;
              btn.innerHTML = originalHtml;
            });
          };
        });

        // Live countdown timer (19:50)
        const timerSpans = Array.from(document.querySelectorAll('span, p')).filter(s => (s.textContent || '').trim().match(/^\d{2}:\d{2}:\d{2}$/));
        if (timerSpans.length > 0) {
          let totalSeconds = 19 * 60 + 50;
          setInterval(function() {
            if (totalSeconds > 0) totalSeconds--;
            const h = String(Math.floor(totalSeconds / 3600)).padStart(2, '0');
            const m = String(Math.floor((totalSeconds % 3600) / 60)).padStart(2, '0');
            const s = String(totalSeconds % 60).padStart(2, '0');
            timerSpans.forEach(el => el.textContent = h + ':' + m + ':' + s);
          }, 1000);
        }
      }

      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
      } else {
        init();
      }
    })();
  </script>

  
